content.text:
{
  "name": "参数控制模块",
  "name_en": "Parameter Control Module",
  "manufacturer": "",
  "description": "用于实验控制软件中管理参数、响应设置变更，并通过 TCP/IP 或 LECO 与远端仪器或服务通信的通用控制模块。本证据不足以对应到某一台明确的物理实验设备。",
  "description_en": "A general control module used in laboratory control software to manage parameters, react to setting changes, and communicate with remote instruments or services over TCP/IP or LECO. The evidence does not support identification of a specific physical laboratory device.",
  "tag_hints": [
    "parameter management",
    "TCP/IP instrument communication",
    "LECO communication",
    "lab automation",
    "remote control",
    "instrument settings"
  ],
  "actions": [
    {
      "action_name": "auto-value_changed",
      "description": "处理用户在设置界面中修改参数时触发的事件。",
      "description_en": "Handle events triggered when a user changes parameters in the settings interface."
    },
    {
      "action_name": "auto-connect_tcp_ip",
      "description": "通过 TCP/IP 连接远端仪器或服务。",
      "description_en": "Connect to a remote instrument or service over TCP/IP."
    },
    {
      "action_name": "auto-connect_leco",
      "description": "连接或断开 LECO 通信客户端。",
      "description_en": "Connect or disconnect the LECO communication client."
    },
    {
      "action_name": "auto-process_tcpip_cmds",
      "description": "处理收到的 TCP/IP 状态或命令信息。",
      "description_en": "Process received TCP/IP status or command information."
    }
  ]
}

